from openpyxl.utils import FORMULAE
from pathlib import Path
import json, sys
p='/root/output/result.xlsx'
wb=load_workbook(p, data_only=False)
ws=wb['Task']
print('PERCENTILE in openpyxl FORMULAE:', 'PERCENTILE' in FORMULAE)
# openpyxl formula tokenizer for percentile
from openpyxl.formula import Tokenizer
for f in [ws['H46'].value, ws['H47'].value]:
    toks=Tokenizer(f).items
    print(f, 'tokens:', [(t.value,t.type,t.subtype) for t in toks])
# data_only check for #NAME? cached values (openpyxl cannot calculate, but will expose cached results if workbook had them)
wbd=load_workbook(p, data_only=True)
for addr in ['H46','H47']:
    v=wbd['Task'][addr].value
    print('data_only', addr, repr(v))
# exact formula coverage
errors=[]
# lookup formula ranges
for r in list(range(12,18))+list(range(19,25))+list(range(26,32)):
    for c in range(8,13):
        col=get_column_letter(c)
        exp=f'=INDEX(Data!$H$21:$L$38,MATCH($D{r},Data!$D$21:$D$38,0),MATCH({col}$10,Data!$H$4:$L$4,0))'
        if ws.cell(r,c).value != exp:
            errors.append((f'{col}{r}', ws.cell(r,c).value, exp))
# headroom
for off,r in enumerate(range(35,41)):
    for c in range(8,13):
        col=get_column_letter(c)
        exp=f'=({col}{12+off}-{col}{19+off})/{col}{26+off}*100'
        if ws.cell(r,c).value != exp:
            errors.append((f'{col}{r}', ws.cell(r,c).value, exp))
# summaries
for c in range(8,13):
    col=get_column_letter(c)
    exps={42:f'=MIN({col}35:{col}40)',43:f'=MAX({col}35:{col}40)',44:f'=MEDIAN({col}35:{col}40)',45:f'=AVERAGE({col}35:{col}40)',46:f'=PERCENTILE({col}35:{col}40,0.25)',47:f'=PERCENTILE({col}35:{col}40,0.75)',50:f'=SUMPRODUCT({col}35:{col}40,{col}26:{col}31)/SUM({col}26:{col}31)'}
    for r,exp in exps.items():
        if ws.cell(r,c).value != exp:
            errors.append((f'{col}{r}', ws.cell(r,c).value, exp))
print('formula errors:', len(errors))
if errors:
    for e in errors[:10]: print(e)
# sheet names
print('sheet names exact:', wb.sheetnames == ['Task','Data'], wb.sheetnames)
# empties
empty=[]
for r1,r2 in [(12,17),(19,24),(26,31),(35,40),(42,47),(50,50)]:
    for r in range(r1,r2+1):
        for c in range(8,13):
            if ws.cell(r,c).value in (None,''):
                empty.append(f'{get_column_letter(c)}{r}')
print('empty count:', len(empty), empty[:10])
# compare source and output style IDs and dimensional props
src=load_workbook('/root/data/workbook.xlsx', data_only=False)
style_diffs=[]
for sname in ['Task','Data']:
    sws=src[sname]; ows=wb[sname]
    if sws.max_row != ows.max_row or sws.max_column != ows.max_column:
        print('dimension diff', sname, (sws.max_row,sws.max_column), (ows.max_row,ows.max_column))
    maxr=max(sws.max_row, ows.max_row); maxc=max(sws.max_column, ows.max_column)
    for r in range(1,maxr+1):
        for c in range(1,maxc+1):
            if sws.cell(r,c)._style != ows.cell(r,c)._style:
                style_diffs.append(f'{sname}!{get_column_letter(c)}{r}')
            if sws.cell(r,c).number_format != ows.cell(r,c).number_format:
                style_diffs.append(f'{sname}!{get_column_letter(c)}{r}:numfmt')
print('style diff count:', len(style_diffs))
# widths/heights
width_diffs=[]
for sname in ['Task','Data']:
    sws=src[sname]; ows=wb[sname]
    keys=set(sws.column_dimensions.keys()) | set(ows.column_dimensions.keys())
    for k in keys:
        if sws.column_dimensions[k].width != ows.column_dimensions[k].width:
            width_diffs.append(f'{sname}!{k}')
    rkeys=set(sws.row_dimensions.keys()) | set(ows.row_dimensions.keys())
    for k in rkeys:
        if sws.row_dimensions[k].height != ows.row_dimensions[k].height:
            width_diffs.append(f'{sname}!row{k}')
print('dimension format diffs:', len(width_diffs), width_diffs[:10])
# content outside write ranges unchanged (formulas and values)
allowed=set()
for r1,r2 in [(12,17),(19,24),(26,31),(35,40),(42,47),(50,50)]:
    for r in range(r1,r2+1):
        for c in range(8,13):
            allowed.add(('Task',r,c))
content_diffs=[]
for sname in ['Task','Data']:
    sws=src[sname]; ows=wb[sname]
    for r in range(1,max(sws.max_row,ows.max_row)+1):
        for c in range(1,max(sws.max_column,ows.max_column)+1):
            if (sname,r,c) not in allowed and sws.cell(r,c).value != ows.cell(r,c).value:
                content_diffs.append(f'{sname}!{get_column_letter(c)}{r}: {sws.cell(r,c).value!r}->{ows.cell(r,c).value!r}')
print('outside content diffs:', len(content_diffs))
for d in content_diffs[:10]: print(d)
